CREATE TABLE IF NOT EXISTS candidates (candidate_id text PRIMARY KEY, idempotency_key text UNIQUE NOT NULL, payload jsonb NOT NULL, payload_hash text NOT NULL, created_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS review_rounds (candidate_id text NOT NULL REFERENCES candidates(candidate_id), round integer NOT NULL, kind text NOT NULL CHECK (kind IN ('initial','scheduled')), due_at timestamptz, verdict_id text UNIQUE, PRIMARY KEY(candidate_id,round));
CREATE TABLE IF NOT EXISTS verdict_events (sequence bigserial PRIMARY KEY, decision_id text UNIQUE NOT NULL, candidate_id text NOT NULL, round integer NOT NULL, action text NOT NULL, reviewed_at timestamptz NOT NULL, next_review_at timestamptz, UNIQUE(candidate_id,round), FOREIGN KEY(candidate_id,round) REFERENCES review_rounds(candidate_id,round));
CREATE TABLE IF NOT EXISTS application_receipts (idempotency_key text PRIMARY KEY, payload_hash text NOT NULL, decision_id text NOT NULL REFERENCES verdict_events(decision_id), applied_at timestamptz NOT NULL, result text NOT NULL CHECK (result IN ('applied','already_applied')));
